-- Migration 441: intake XJZ NPC dialog text candidates.
-- Function: NPC and quest dialog text. The rows remain candidates until NPC and flow binding are proven.

CREATE TABLE IF NOT EXISTS god2_research.xjz_npc_dialog_candidates (
  dialog_id BIGINT NOT NULL COMMENT 'XJZ 對話 ID',
  message_id INT NULL COMMENT '客戶端訊息 ID',
  source_kind VARCHAR(100) NOT NULL COMMENT '對話來源類型',
  speaker_or_branch_zh_tw VARCHAR(200) NULL COMMENT '說話者或分支',
  text_zh_tw TEXT NOT NULL COMMENT '對話繁體中文內容',
  source_file VARCHAR(500) NOT NULL COMMENT '證據來源檔案',
  source_line INT NULL COMMENT '證據來源行號',
  evidence_status_zh_tw VARCHAR(100) NOT NULL COMMENT '目前證據狀態',
  is_placeholder TINYINT(1) NOT NULL COMMENT '是否為尚未解析的占位文字',
  formal_npc_id BIGINT NULL COMMENT '正式 NPC ID',
  formal_link_status_zh_tw VARCHAR(80) NOT NULL DEFAULT '待 NPC 或任務流程綁定' COMMENT '正式綁定狀態',
  created_at_utc DATETIME(6) NOT NULL DEFAULT UTC_TIMESTAMP(6) COMMENT '建立 UTC 時間',
  PRIMARY KEY (dialog_id),
  KEY ix_xjz_npc_dialog_source (source_kind),
  KEY ix_xjz_npc_dialog_message (message_id),
  KEY ix_xjz_npc_dialog_placeholder (is_placeholder),
  CONSTRAINT ck_xjz_npc_dialog_placeholder CHECK (is_placeholder IN (0,1))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='XJZ 客戶端還原 NPC/任務對話候選';

TRUNCATE TABLE god2_research.xjz_npc_dialog_candidates;

INSERT INTO god2_research.xjz_npc_dialog_candidates
  (dialog_id, message_id, source_kind, speaker_or_branch_zh_tw, text_zh_tw,
   source_file, source_line, evidence_status_zh_tw, is_placeholder)
VALUES
(16058,1,'DailyMission01','','唉~小仙童你去幫我收集材料吧~讓我練一下合成~','server_implementation/data/extracted_csvz/Data2/Patch/Comm/DailyMission01.csv',3,'客戶端文字資料',0),
(16059,2,'DailyMission01','','我需要聖樵原野的曲湖上的仙界靈草5個。','server_implementation/data/extracted_csvz/Data2/Patch/Comm/DailyMission01.csv',4,'客戶端文字資料',0),
(16060,3,'DailyMission01','','太好了！合出來的東西，多的就當是我賞你的~沒多就算啦。','server_implementation/data/extracted_csvz/Data2/Patch/Comm/DailyMission01.csv',5,'客戶端文字資料',0),
(16061,4,'DailyMission01','','不知道那個愛哭鬼她練到多少級了，希望差我很多。','server_implementation/data/extracted_csvz/Data2/Patch/Comm/DailyMission01.csv',6,'客戶端文字資料',0),
(16062,5,'DailyMission01','','仙童哥哥、姊姊，能幫我收集材料嗎?','server_implementation/data/extracted_csvz/Data2/Patch/Comm/DailyMission01.csv',7,'客戶端文字資料',0),
(16063,6,'DailyMission01','','人家想要聖樵原野的曲湖上的仙界神花，5個就好。','server_implementation/data/extracted_csvz/Data2/Patch/Comm/DailyMission01.csv',8,'客戶端文字資料',0),
(16064,7,'DailyMission01','','仙童哥哥、姊姊，我把它變成別的東西了...都給你吧~','server_implementation/data/extracted_csvz/Data2/Patch/Comm/DailyMission01.csv',9,'客戶端文字資料',0),
(16065,8,'DailyMission01','','嗯，這樣應該就能贏過那個討厭鬼了吧?!','server_implementation/data/extracted_csvz/Data2/Patch/Comm/DailyMission01.csv',10,'客戶端文字資料',0),
(16066,9,'DailyMission01','','小仙童，我一直想要天池內的神魚，雪白、墨黑、透明、七彩錦鱗魚，可惜我是凡人，無法上仙界天池內找尋。你是否能幫忙帶其中一種下來給我?只要一尾，我的畢生大作即可問世，拜托了。','server_implementation/data/extracted_csvz/Data2/Patch/Comm/DailyMission01.csv',11,'客戶端文字資料',0),
(16067,10,'DailyMission01','','崑侖仙界天池內有神奇的錦鱗魚，分別是雪白、墨黑、透明、七彩，其中透明與七彩最為罕見。\n當然如果你身上有比較罕見的，我會先從罕見的開始拿喔~嘿嘿~','server_implementation/data/extracted_csvz/Data2/Patch/Comm/DailyMission01.csv',12,'客戶端文字資料',0),
(16068,11,'DailyMission01','','這真是太神奇了，好特別的色澤，我就以這微薄的經驗值跟仙幣報答你吧，謝謝你。','server_implementation/data/extracted_csvz/Data2/Patch/Comm/DailyMission01.csv',13,'客戶端文字資料',0),
(16069,12,'DailyMission01','','這麼特別的魚，我該用煮的還是用蒸的好呢？這還真是苦惱啊…','server_implementation/data/extracted_csvz/Data2/Patch/Comm/DailyMission01.csv',14,'客戶端文字資料',0),
(16070,13,'DailyMission01','','唉，真是老糊塗竟然將包裹掉在聖譙原野的火雲碑附遌，可以幫忙取回嗎？','server_implementation/data/extracted_csvz/Data2/Patch/Comm/DailyMission01.csv',15,'客戶端文字資料',0),
(16071,14,'DailyMission01','','幫個忙吧，就在火雲碑那邊。請帶著給你的「遺落的包裹清單」','server_implementation/data/extracted_csvz/Data2/Patch/Comm/DailyMission01.csv',16,'客戶端文字資料',0),
(16072,15,'DailyMission01','','終於找回來了嗎?真是感謝啊，我多準備了一些東西，運氣好相同的獎勵可以拿到兩份喔。','server_implementation/data/extracted_csvz/Data2/Patch/Comm/DailyMission01.csv',17,'客戶端文字資料',0),
(16073,16,'DailyMission01','','這可真是幫了我個大忙!!還好有找回包裹。還真是一直勞煩你，我有多準備一些謝禮給你。運氣好相同獎勵可以拿到兩份喔。','server_implementation/data/extracted_csvz/Data2/Patch/Comm/DailyMission01.csv',18,'客戶端文字資料',0),
(16074,17,'DailyMission01','','小兄弟呀，幫我把這東西拿去給葛城的奚祈鑑定一下，看看是真是假。','server_implementation/data/extracted_csvz/Data2/Patch/Comm/DailyMission01.csv',19,'客戶端文字資料',0),
(16075,18,'DailyMission01','','將東西拿給葛城的奚祈鑑定。\n(聽說葛城有出土仙界的五彩玄鵲，而且還擺在雜貨店賣…這…真是暴殄天物啊。)','server_implementation/data/extracted_csvz/Data2/Patch/Comm/DailyMission01.csv',20,'客戶端文字資料',0),
(16076,19,'DailyMission01','','小兄弟，謝謝你啦，這錢跟道具就送你吧~','server_implementation/data/extracted_csvz/Data2/Patch/Comm/DailyMission01.csv',21,'客戶端文字資料',0),
(16077,20,'DailyMission01','','(你發現這古怪的人，一直在看他手上的兩尊羅漢雕像互打)','server_implementation/data/extracted_csvz/Data2/Patch/Comm/DailyMission01.csv',22,'客戶端文字資料',0),
(16078,21,'DailyMission01','','小兄弟呀，幫我把這東西拿去給九天冰屋的古旝鑑定一下，看看是真是假。','server_implementation/data/extracted_csvz/Data2/Patch/Comm/DailyMission01.csv',23,'客戶端文字資料',0),
(16079,22,'DailyMission01','','小兄弟呀，幫我把這東西拿去給焰霜鎮的甄麒鑑定一下，看看是真是假。','server_implementation/data/extracted_csvz/Data2/Patch/Comm/DailyMission01.csv',24,'客戶端文字資料',0),
(16080,23,'DailyMission01','','小兄弟呀，幫我把這東西拿去給茄城的易褓鑑定一下，看看是真是假。','server_implementation/data/extracted_csvz/Data2/Patch/Comm/DailyMission01.csv',25,'客戶端文字資料',0),
(16081,24,'DailyMission01','','將東西拿給九天冰屋的古旝鑑定。\n(聽說那邊的雜貨鋪有賣鎮魂霸印，不知道是真還是假？)','server_implementation/data/extracted_csvz/Data2/Patch/Comm/DailyMission01.csv',26,'客戶端文字資料',0),
(16082,25,'DailyMission01','','將東西拿給焰霜鎮的甄麒鑑定。\n(陰陽兩儀盤，聽說那可以解開焰霜為什麼一邊是火島，一邊是冰島的秘密。)','server_implementation/data/extracted_csvz/Data2/Patch/Comm/DailyMission01.csv',27,'客戶端文字資料',0),
(16083,26,'DailyMission01','','將東西拿給茄城的易褓鑑定。\n(聽說茄城前陣子從空中掉下很多仙雲劍柄，看來應該是仙界又有神魔大戰吧？劍柄似乎被擺在雜貨店裡…)','server_implementation/data/extracted_csvz/Data2/Patch/Comm/DailyMission01.csv',28,'客戶端文字資料',0),
(16084,27,'DailyMission01','','是雲峰那老頭要你拿這東西給我鑑定？','server_implementation/data/extracted_csvz/Data2/Patch/Comm/DailyMission01.csv',29,'客戶端文字資料',0),
(16085,28,'DailyMission01','','這不用看都知道是假的，那瘋老頭又想拿這來騙錢，這邊雜貨店有其他古物，那應該也是假的，你買回去捉弄捉弄那老頭吧，跟他換值錢的東西吧。','server_implementation/data/extracted_csvz/Data2/Patch/Comm/DailyMission01.csv',30,'客戶端文字資料',0),
(16086,29,'DailyMission01','','嗯，仔細觀察後……兩個都是假的。','server_implementation/data/extracted_csvz/Data2/Patch/Comm/DailyMission01.csv',31,'客戶端文字資料',0),
(16087,30,'DailyMission01','','(你發現這古董鑑定商，似乎是在看他手上的秘籍)','server_implementation/data/extracted_csvz/Data2/Patch/Comm/DailyMission01.csv',32,'客戶端文字資料',0),
(16088,31,'DailyMission01','','嗯，仔細觀察後……兩個都是假的。','server_implementation/data/extracted_csvz/Data2/Patch/Comm/DailyMission01.csv',33,'客戶端文字資料',0),
(16089,32,'DailyMission01','','你把這兩個都拿回去給雲峰那老頭吧。','server_implementation/data/extracted_csvz/Data2/Patch/Comm/DailyMission01.csv',34,'客戶端文字資料',0),
(16090,33,'DailyMission01','','帶著翡翠玉壺與五彩玄鵲回去找裘奇。','server_implementation/data/extracted_csvz/Data2/Patch/Comm/DailyMission01.csv',35,'客戶端文字資料',0),
(16091,34,'DailyMission01','','帶著狂獅魂珠與鎮魂霸印回去找裘奇。','server_implementation/data/extracted_csvz/Data2/Patch/Comm/DailyMission01.csv',36,'客戶端文字資料',0),
(16092,35,'DailyMission01','','帶著天界符文與陰陽兩儀盤回去找裘奇。','server_implementation/data/extracted_csvz/Data2/Patch/Comm/DailyMission01.csv',37,'客戶端文字資料',0),
(16093,36,'DailyMission01','','帶著仙女發釵與仙雲劍柄回去找裘奇。','server_implementation/data/extracted_csvz/Data2/Patch/Comm/DailyMission01.csv',38,'客戶端文字資料',0),
(16094,37,'DailyMission01','','你回來啦，我的東西呢？','server_implementation/data/extracted_csvz/Data2/Patch/Comm/DailyMission01.csv',39,'客戶端文字資料',0),
(16095,38,'DailyMission01','','這怎麼看都像真的啊！？為什麼要說是假的？(罷了，我身邊只有這些怪東西，就送你幾個不值錢的吧~)','server_implementation/data/extracted_csvz/Data2/Patch/Comm/DailyMission01.csv',40,'客戶端文字資料',0),
(16096,39,'DailyMission01','','這老頭看起來很落寞。','server_implementation/data/extracted_csvz/Data2/Patch/Comm/DailyMission01.csv',41,'客戶端文字資料',0),
(16097,40,'DailyMission01','','哪個才是真？哪個才是假？','server_implementation/data/extracted_csvz/Data2/Patch/Comm/DailyMission01.csv',42,'客戶端文字資料',0),
(16098,41,'DailyMission01','','小仙童，你看人界，似乎有黑影在蠢蠢慾動。我已經先派仙界守衛兵長下凡，駐守在人間了。你幫我把這令旗，拿給守衛兵長吧。','server_implementation/data/extracted_csvz/Data2/Patch/Comm/DailyMission01.csv',43,'客戶端文字資料',0),
(16099,42,'DailyMission01','','嗯，我知道了，就拜托你把這警戒令交給駐守在楓華鎮仙界的守衛兵長吧。','server_implementation/data/extracted_csvz/Data2/Patch/Comm/DailyMission01.csv',44,'客戶端文字資料',0),
(16100,43,'DailyMission01','','大仙童的消息果力村這邊收到了，就麻煩小仙童把這警戒令交給駐守在果力村仙界的守衛兵長吧。','server_implementation/data/extracted_csvz/Data2/Patch/Comm/DailyMission01.csv',45,'客戶端文字資料',0),
(16101,44,'DailyMission01','','嗯，這下可得小心堤防了，小仙童就拜托你把這警戒令交給駐守在莫莫聚落仙界的守衛兵長吧。','server_implementation/data/extracted_csvz/Data2/Patch/Comm/DailyMission01.csv',46,'客戶端文字資料',0),
(16102,45,'DailyMission01','','真是可靠的小仙童阿，人界的未來可要靠你們了，我這邊已經了解情況了，就請你將警戒令轉交給駐守在茄城仙界的守衛兵長吧。','server_implementation/data/extracted_csvz/Data2/Patch/Comm/DailyMission01.csv',47,'客戶端文字資料',0),
(16103,46,'DailyMission01','','任務了解，請把這警戒令交給下一個駐守在果城仙界的守衛兵長。','server_implementation/data/extracted_csvz/Data2/Patch/Comm/DailyMission01.csv',48,'客戶端文字資料',0),
(16104,47,'DailyMission01','','咦?又來了嗎?\n天啊，他們每天這樣來一張都不會煩的嗎?罷了罷了，把這警戒令拿給駐守在青采聚落仙界的守衛兵長吧。','server_implementation/data/extracted_csvz/Data2/Patch/Comm/DailyMission01.csv',49,'客戶端文字資料',0),
(16105,48,'DailyMission01','','多謝，還得再麻煩你將這份警戒令交給駐守在九黎平原(寒羽荒原關卡口)的仙界守衛兵長了。','server_implementation/data/extracted_csvz/Data2/Patch/Comm/DailyMission01.csv',50,'客戶端文字資料',0),
(16106,49,'DailyMission01','','加油阿，小仙童，到我這已經快要結束了，你可要努力點撐過去，那就麻煩你把這份警戒令交給駐守在九黎平原(九尾國境關卡口)的仙界守衛兵長吧。','server_implementation/data/extracted_csvz/Data2/Patch/Comm/DailyMission01.csv',51,'客戶端文字資料',0),
(16107,50,'DailyMission01','','………………………………收到，看來我是最後一個了，就請你把這將警戒令還給在崑侖仙界的大仙童吧。','server_implementation/data/extracted_csvz/Data2/Patch/Comm/DailyMission01.csv',52,'客戶端文字資料',0),
(16108,51,'DailyMission01','','有邪惡氣息正在蔓延，看來人間又要大亂了。','server_implementation/data/extracted_csvz/Data2/Patch/Comm/DailyMission01.csv',53,'客戶端文字資料',0),
(16109,52,'DailyMission01','','嗯，我收到大仙童的指示了。謝謝你，小仙童。','server_implementation/data/extracted_csvz/Data2/Patch/Comm/DailyMission01.csv',54,'客戶端文字資料',0),
(16110,53,'DailyMission01','','大仙童一發不語的盯著人間看，似乎是在找尋什麼？','server_implementation/data/extracted_csvz/Data2/Patch/Comm/DailyMission01.csv',55,'客戶端文字資料',0),
(16111,54,'DailyMission01','','仙界什麼時候才會派人把武器帶下來？','server_implementation/data/extracted_csvz/Data2/Patch/Comm/DailyMission01.csv',56,'客戶端文字資料',0),
(16112,55,'DailyMission01','','辛苦你了，小仙童。','server_implementation/data/extracted_csvz/Data2/Patch/Comm/DailyMission01.csv',57,'客戶端文字資料',0),
(16113,56,'DailyMission01','','這點經驗、道具就送你，讓你提升能力吧。','server_implementation/data/extracted_csvz/Data2/Patch/Comm/DailyMission01.csv',58,'客戶端文字資料',0),
(16114,57,'DailyMission01','','吾家族世世代代守護著這座陵寢，如今被這群覬覦寶藏的鼠輩刁擾、破壞…，殺了那些囂張跋扈的「盜墓賊」，取下刀柄，回來找我。','server_implementation/data/extracted_csvz/Data2/Patch/Comm/DailyMission01.csv',59,'客戶端文字資料',0),
(16115,58,'DailyMission01','','吾家族世世代代守護著這座陵寢，如今被這群窺覬奇兵的雜卒刁擾、破壞…，殺了那些無頭無腦的「秘密部隊」，取下徽章，回來找我。','server_implementation/data/extracted_csvz/Data2/Patch/Comm/DailyMission01.csv',60,'客戶端文字資料',0),
(16116,59,'DailyMission01','','吾家族世世代代守護著這座陵寢，如今被這群貪婪神功的孬種刁擾、破壞…，殺了那些心存邪念的「刀劍師傅」，取下手鐲，回來找我。','server_implementation/data/extracted_csvz/Data2/Patch/Comm/DailyMission01.csv',61,'客戶端文字資料',0),
(16117,60,'DailyMission01','','吾家族世世代代守護著這座陵寢，替我去裡面安撫受到驚嚇的「遺族亡魂」，祂們會在裡面亂飄………取得感謝文，回來找我。','server_implementation/data/extracted_csvz/Data2/Patch/Comm/DailyMission01.csv',62,'客戶端文字資料',0),
(16118,61,'DailyMission01','','殺了囂張跋扈的盜墓賊，取下刀柄15個，回來找我。','server_implementation/data/extracted_csvz/Data2/Patch/Comm/DailyMission01.csv',63,'客戶端文字資料',0),
(16119,62,'DailyMission01','','殺了無頭無腦的秘密部隊，取下徽章10個，回來找我。','server_implementation/data/extracted_csvz/Data2/Patch/Comm/DailyMission01.csv',64,'客戶端文字資料',0),
(16120,63,'DailyMission01','','殺了心存邪念的刀劍師傅，取下手鐲5個，回來找我。','server_implementation/data/extracted_csvz/Data2/Patch/Comm/DailyMission01.csv',65,'客戶端文字資料',0),
(16121,64,'DailyMission01','','安撫受到驚嚇的「遺族亡魂」，取得感謝文10個，回來找我。','server_implementation/data/extracted_csvz/Data2/Patch/Comm/DailyMission01.csv',66,'客戶端文字資料',0),
(16122,65,'DailyMission01','','感謝你的幫忙，小仙童，這些小東西就當做謝禮，謝謝你。','server_implementation/data/extracted_csvz/Data2/Patch/Comm/DailyMission01.csv',67,'客戶端文字資料',0),
